#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long t;
    cin >> n >> m >> t;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    vector<vector<long long>> dist(n, vector<long long>(n, INF));
    for (int i = 0; i < n; i++) dist[i][i] = 0;
    for (const vector<long long>& e : edges) {
        dist[e[0] - 1][e[1] - 1] = min(dist[e[0] - 1][e[1] - 1], e[2]);
        dist[e[1] - 1][e[0] - 1] = min(dist[e[1] - 1][e[0] - 1], e[2]);
    }
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
            }
        }
    }
    int bestCity = -1, bestCount = (int)n + 1;
    for (int i = 0; i < n; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (j != i && dist[i][j] <= t) count++;
        }
        if (count <= bestCount) {
            bestCount = count;
            bestCity = i + 1;
        }
    }
    cout << bestCity << "\n";

    return 0;
}

