import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long t = Long.parseLong(next());
        long[][] edges = new long[(int) m][3];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int cities = (int) n;
        long INF = 1000000000000000000L;
        long[][] dist = new long[cities][cities];
        for (long[] row : dist) Arrays.fill(row, INF);
        for (int i = 0; i < cities; i++) dist[i][i] = 0;
        for (long[] e : edges) {
            int u = (int) e[0] - 1, v = (int) e[1] - 1;
            dist[u][v] = Math.min(dist[u][v], e[2]);
            dist[v][u] = Math.min(dist[v][u], e[2]);
        }
        for (int k = 0; k < cities; k++) {
            for (int i = 0; i < cities; i++) {
                for (int j = 0; j < cities; j++) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
        int bestCity = -1, bestCount = cities + 1;
        for (int i = 0; i < cities; i++) {
            int count = 0;
            for (int j = 0; j < cities; j++) {
                if (j != i && dist[i][j] <= t) count++;
            }
            if (count <= bestCount) {
                bestCount = count;
                bestCity = i + 1;
            }
        }
        System.out.println(bestCity);
    }
}
